import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2017Q2 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2017Q2 Ceph社区季度进展报告","date":"2017-06-01T00:00:00.000Z","updated":"2017-06-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017Q2_Ceph社区季度总结.md","filePath":"posts/2017/2017Q2_Ceph社区季度总结.md","lastUpdated":1780460162000}'),l={name:"posts/2017/2017Q2_Ceph社区季度总结.md"};function h(n,e,i,s,_,m){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="ceph-社区-2017-q2-季度进展报告" tabindex="-1">Ceph 社区 2017 Q2 季度进展报告 <a class="header-anchor" href="#ceph-社区-2017-q2-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2017 Q2 季度进展报告&quot;">​</a></h1><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度（2017年3月下旬至6月）Ceph 社区的讨论高度集中在以下几个方向：</p><p><strong>BlueStore 性能优化</strong>是本季度最核心的主题，贯穿几乎所有 Performance Weekly 会议。涉及缓存管理、限流机制、内存使用、RocksDB 后端调优等多个子方向，详见 <a href="./2017-APR-05_-_Ceph_Performance_Weekly.html">2017-APR-05 Performance Weekly</a>、<a href="/VideoSummary/posts/2017/2017-MAY-18_-_-_Ceph_Performance_Weekly.html">2017-MAY-18 Performance Weekly</a>)。</p><p><strong>Luminous 版本收尾</strong>是本季度的里程碑目标，多个会议中的 PR 合并和功能决策均以&quot;是否纳入 Luminous&quot;为判断标准，详见 <a href="/VideoSummary/posts/2017/2017-APR-12_-_-_Ceph_Developer_Monthly.html">2017-APR-12 Developer Monthly</a>)。</p><p><strong>ARM 平台支持</strong>在本季度获得专题讨论，多家厂商（Cavium、SUSE、Deutsche Telekom）参与，详见 <a href="/VideoSummary/posts/2017/2017-MAY-25_--_Ceph_Tech_Talk_-_Ceph_on_ARM.html">2017-MAY-25 Ceph on ARM</a>)。</p><p><strong>Ceph Manager 功能扩展</strong>，包括 REST API 和配置选项注释，作为 Luminous 的新增能力被重点讨论。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="bluestore-与-rocksdb" tabindex="-1">BlueStore 与 RocksDB <a class="header-anchor" href="#bluestore-与-rocksdb" aria-label="Permalink to &quot;BlueStore 与 RocksDB&quot;">​</a></h3><ul><li><strong>自适应限流（Adaptive Throttle）</strong>：本季度持续迭代，目标是基于目标延迟动态调整限流参数，替代原有的静态配置。见 <a href="/VideoSummary/posts/2017/2017-APR-12_-_-_Ceph_Performance_Weekly.html">2017-APR-12 Performance Weekly</a>)、<a href="/VideoSummary/posts/2017/2017-MAY-11_-_-_Ceph_Performance_Weekly.html">2017-MAY-11 Performance Weekly</a>)。</li><li><strong>RocksDB Compaction Read-Ahead</strong>：Mark 验证了启用该功能后压缩期间读取时间从 95% 降至 18%，显著改善 BlueStore 在压缩期间的性能，见 <a href="/VideoSummary/posts/2017/2017-MAY-04_-_-_Ceph_Performance_Weekly.html">2017-MAY-04 Performance Weekly</a>)。</li><li><strong>BlueFS 同步写（sync write）选项</strong>：新增 BlueFS 同步提交功能，提高事务提交可靠性，见 <a href="./2017-JUN-01_-_Ceph_Performance_Weekly.html">2017-JUN-01 Performance Weekly</a>。</li><li><strong>缓存池扩展</strong>：BlueStore 新增 5 个缓存池，提高数据可见性和跟踪能力。</li><li><strong>B-Tree 替代 STL map</strong>：用于 PG temp mapping，提升元数据操作效率，见 <a href="./2017-MAY-25_-_Ceph_Performance_Weekly.html">2017-MAY-25 Performance Weekly</a>。</li><li><strong>内存复制优化</strong>：多个 PR 致力于在写路径上避免不必要的内存拷贝，见 <a href="/VideoSummary/posts/2017/2017-MAY-18_-_-_Ceph_Performance_Weekly.html">2017-MAY-18 Performance Weekly</a>)。</li></ul><h3 id="osd-与-rados" tabindex="-1">OSD 与 RADOS <a class="header-anchor" href="#osd-与-rados" aria-label="Permalink to &quot;OSD 与 RADOS&quot;">​</a></h3><ul><li><strong>PG 重映射（PG Remapping）</strong>：Sage 提出允许在 PG 已映射后重新映射的功能，解决长期存在的数据分布优化需求，见 <a href="/VideoSummary/posts/2017/2017-MAR-22_-_-_Ceph_Performance_Weekly.html">2017-MAR-22 Performance Weekly</a>)。</li><li><strong>异步恢复（Async Recovery）</strong>：Josh 推进异步恢复机制，阿里巴巴团队同步贡献了同步恢复和部分恢复的优化，见 <a href="/VideoSummary/posts/2017/2017-MAY-04_-_-_Ceph_Performance_Weekly.html">2017-MAY-04 Performance Weekly</a>)。</li><li><strong>Commit Majority功能</strong>：阿里巴巴团队实现了 commit majority，降低平均延迟和延迟抖动，见 <a href="/VideoSummary/posts/2017/2017-MAY-11_-_-_Ceph_Performance_Weekly.html">2017-MAY-11 Performance Weekly</a>)。</li><li><strong>Scrub 作业优先级调整</strong>：已合并，改善后台 scrub 对前台 IO 的影响，见 <a href="/VideoSummary/posts/2017/2017-JUN-08_-_-_Ceph_Performance_Weekly.html">2017-JUN-08 Performance Weekly</a>)。</li></ul><h3 id="async-messenger" tabindex="-1">Async Messenger <a class="header-anchor" href="#async-messenger" aria-label="Permalink to &quot;Async Messenger&quot;">​</a></h3><ul><li>持续优化锁机制，减少锁争用，在 Tesla 平台上验证了性能提升，见 <a href="./2017-MAY-25_-_Ceph_Performance_Weekly.html">2017-MAY-25 Performance Weekly</a>。</li></ul><h3 id="ceph-manager" tabindex="-1">Ceph Manager <a class="header-anchor" href="#ceph-manager" aria-label="Permalink to &quot;Ceph Manager&quot;">​</a></h3><ul><li><strong>REST API</strong>：决定将 REST API 作为 Luminous 的实验性功能纳入，支持 OpenStack Swift 等上层应用集成，见 <a href="/VideoSummary/posts/2017/2017-APR-12_-_-_Ceph_Developer_Monthly.html">2017-APR-12 Developer Monthly</a>)。</li><li><strong>配置选项注释（Config Option Annotations）</strong>：为配置项添加描述、类型、默认值、影响范围、弃用标记等元数据，并通过文档生成工具自动输出文档。</li></ul><h3 id="rbd" tabindex="-1">RBD <a class="header-anchor" href="#rbd" aria-label="Permalink to &quot;RBD&quot;">​</a></h3><ul><li><strong>持久缓存（Persistent Cache）</strong>：基于 Jason 草图的 RBD 持久缓存框架进入开发阶段，当前 IOPS 表现尚待优化，计划支持 unicast 和 scatter-gather，见 <a href="/VideoSummary/posts/2017/2017-JUN-07_-_-_Ceph_Developer_Monthly.html">2017-JUN-07 Developer Monthly</a>)。</li></ul><h3 id="可观测性" tabindex="-1">可观测性 <a class="header-anchor" href="#可观测性" aria-label="Permalink to &quot;可观测性&quot;">​</a></h3><ul><li><strong>Zipkin 追踪框架集成</strong>：Mark 持续推进将 Zipkin 集成到 Ceph 中，用于分布式追踪和性能监控，见 <a href="/VideoSummary/posts/2017/2017-APR-05_-_-_Ceph_Performance_Weekly.html">2017-APR-05 Performance Weekly</a>)。</li></ul><h3 id="语言绑定" tabindex="-1">语言绑定 <a class="header-anchor" href="#语言绑定" aria-label="Permalink to &quot;语言绑定&quot;">​</a></h3><ul><li><strong>Ceph Rust Bindings</strong>：Chris Jones 展示了 Ceph 的 Rust 语言绑定，利用 Rust 内存安全特性封装 librados，见 <a href="./2017-MAR-23_--_Ceph_Tech_Talks_-_Ceph_at_ScaleWriting_Applications_with_Language_Bindings.html">2017-MAR-23 Ceph Tech Talks</a>。</li></ul><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>决策</th><th>内容</th></tr></thead><tbody><tr><td>REST API 纳入 Luminous</td><td>以实验性功能状态发布，后续版本继续完善</td></tr><tr><td>配置选项注释纳入 Luminous</td><td>统一配置文档生成机制</td></tr><tr><td>存储池应用标签（Pool Application Tags）</td><td>添加 <code>application</code> 标签和元数据映射，不强制要求，提供健康警告，见 <a href="/VideoSummary/posts/2017/2017-JUN-07_-_-_Ceph_Developer_Monthly.html">2017-JUN-07 Developer Monthly</a>)</td></tr><tr><td>systemd 自定义集群名称支持移除</td><td>因兼容性问题决定移除，提供升级路径</td></tr><tr><td>OSD 部署工具改用 LVM</td><td>简化 OSD 部署流程，替代过于复杂的 ceph-disk 方案</td></tr><tr><td>BlueStore 元数据后端探索</td><td>开始评估 LMDB 作为元数据存储后端的可行性</td></tr><tr><td>ARM 平台 CI/CD 建设</td><td>决定将 ARM 构建纳入每个发布版本，并在 Jenkins 上建立 CI 流程，见 <a href="/VideoSummary/posts/2017/2017-MAY-25_--_Ceph_Tech_Talk_-_Ceph_on_ARM.html">2017-MAY-25 Ceph on ARM</a>)</td></tr><tr><td>Performance Weekly 会议时间调整</td><td>调整为周四 UTC 11:00，以兼顾不同时区参与者</td></tr></tbody></table><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><p><strong>贡献者与厂商参与</strong></p><ul><li><strong>Red Hat</strong>：Sage Weil、Josh、Greg 等核心开发者持续主导 BlueStore、OSD、恢复机制等方向。</li><li><strong>阿里巴巴</strong>：Mark、Jesse、Gem、CliffJohnson 等工程师深度参与性能优化，贡献了 commit majority、异步恢复等功能，并与社区建立了协作审查机制。</li><li><strong>Cavium / ARM</strong>：Pankaj Brijwasi 等推动 ARM 64 位平台支持，见 <a href="/VideoSummary/posts/2017/2017-MAY-25_--_Ceph_Tech_Talk_-_Ceph_on_ARM.html">2017-MAY-25 Ceph on ARM</a>)。</li><li><strong>SUSE</strong>：提供 ARM 64 位平台的 Ceph 企业存储产品支持。</li><li><strong>Deutsche Telekom</strong>：参与 ARM 平台性能测试和 Luminous 构建验证。</li><li><strong>Canonical</strong>：Chris Wholey 介绍了基于 Juju/Charm 的 Ceph 自动化部署方案，见 <a href="/VideoSummary/posts/2017/2017-MAR-23_--_Ceph_Tech_Talks_-_Ceph_at_Scale_Writing_Applications_with_Language_Bindings.html">2017-MAR-23 Ceph Tech Talks</a>)。</li></ul><p><strong>大规模部署测试</strong></p><ul><li>CERN 部署了约 200 个主机的临时集群，用于验证新代码，见 <a href="/VideoSummary/posts/2017/2017-MAY-25_-_-_Ceph_Performance_Weekly.html">2017-MAY-25 Performance Weekly</a>)。</li></ul><p><strong>会议与活动</strong></p><ul><li>本季度持续举办 Ceph Performance Weekly（每周）、Ceph Developer Monthly（每月）和 Ceph Tech Talks 系列。</li><li>Tech Talks 本季度涵盖&quot;Ceph at Scale / Language Bindings&quot;和&quot;Ceph on ARM&quot;两个专题。</li></ul><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度讨论，预计 2017 Q3 的重点方向包括：</p><ol><li><strong>Luminous 正式发布</strong>：本季度大量功能已进入收尾阶段，Luminous 发布是 Q3 最重要的里程碑。</li><li><strong>BlueStore 稳定性与性能持续提升</strong>：自适应限流、内存管理、LMDB 元数据后端等方向将进入验证阶段。</li><li><strong>Ceph Manager 生态完善</strong>：REST API 和配置注释落地后，预计会有更多 Dashboard 和运维工具基于 Manager 构建。</li><li><strong>ARM 平台 CI 建设落地</strong>：ARM 构建纳入正式发布流程，二进制包开始提供。</li><li><strong>RBD 持久缓存成熟</strong>：当前 IOPS 性能问题待解决，预计 Q3 会有更完整的实现。</li><li><strong>阿里巴巴贡献合并</strong>：commit majority、部分恢复等 PR 预计进入主线审查。</li><li><strong>OSD 部署工具 LVM 化</strong>：ceph-volume 工具预计在 Q3 进一步完善并推广。</li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2017/2017-APR-05_-_-_Ceph_Performance_Weekly.html">2017-APR-05 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-APR-12_-_-_Ceph_Developer_Monthly.html">2017-APR-12 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-APR-12_-_-_Ceph_Performance_Weekly.html">2017-APR-12 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-APR-27_-_-_Ceph_Performance_Weekly.html">2017-APR-27 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-JUN-01_-_-_Ceph_Performance_Weekly.html">2017-JUN-01 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-JUN-07_-_-_Ceph_Developer_Monthly.html">2017-JUN-07 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-JUN-08_-_-_Ceph_Performance_Weekly.html">2017-JUN-08 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-JUN-15_-_-_Ceph_Performance_Weekly.html">2017-JUN-15 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAR-22_-_-_Ceph_Performance_Weekly.html">2017-MAR-22 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAR-23_--_Ceph_Tech_Talks_-_Ceph_at_Scale_Writing_Applications_with_Language_Bindings.html">2017-MAR-23 -- Ceph Tech Talks: Ceph at Scale &amp; Writing Applications with Language Bindings</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAR-29_-_-_Ceph_Performance_Weekly.html">2017-MAR-29 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAY-04_-_-_Ceph_Performance_Weekly.html">2017-MAY-04 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAY-11_-_-_Ceph_Performance_Weekly.html">2017-MAY-11 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAY-18_-_-_Ceph_Performance_Weekly.html">2017-MAY-18 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAY-25_--_Ceph_Tech_Talk_-_Ceph_on_ARM.html">2017-MAY-25 -- Ceph Tech Talk: Ceph on ARM</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAY-25_-_-_Ceph_Performance_Weekly.html">2017-MAY-25 :: Ceph Performance Weekly</a>)</li></ul>',41)])])}const d=a(l,[["render",h]]);export{c as __pageData,d as default};
